draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // head
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50 + 20 * Math.sin(t));
  ctx.stroke();

  // left arm
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 - 30 + 10 * Math.cos(t), H/2 + 40 + 10 * Math.sin(t));
  ctx.stroke();

  // right arm
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + 30 + 10 * Math.cos(t), H/2 + 40 + 10 * Math.sin(t));
  ctx.stroke();

  // left leg
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50 + 20 * Math.sin(t));
  ctx.lineTo(W/2 - 20 + 10 * Math.cos(t), H/2 + 80 + 10 * Math.sin(t));
  ctx.stroke();

  // right leg
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50 + 20 * Math.sin(t));
  ctx.lineTo(W/2 + 20 + 10 * Math.cos(t), H/2 + 80 + 10 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
